contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: send a deposit of exactly MinDeposit and then read the recorded balance.
    // The rule: after depositing exactly MinDeposit, the balances[msg.sender] remains unchanged (== 0 for a fresh sender).
    function run(uint256 amt) public payable {
        // require caller provided the ether to forward
        require(address(this).balance >= amt);

        // Precondition: amt should be exactly the contract's MinDeposit
        uint256 min = c.MinDeposit();
        require(amt == min);

        // Ensure starting balance observed for this contract in c is 0 (fresh participant).
        // balances is public so getter exists: balances(address) returns uint
        uint256 before = c.balances(address(this));
        require(before == 0);

        // Perform the deposit call forwarding amt wei
        c.Deposit{value: amt}();

        // Read balance after deposit
        uint256 after = c.balances(address(this));

        // Assertion: after must still equal before (i.e., equal deposits of exactly MinDeposit are rejected and do not change stored balance)
        assert(after == before);
    }

    // Allow the test contract to receive ETH so it can forward it to c
    receive() external payable {}
}

