contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drive the contract: send a deposit amount and then check observed balance change
    function runTest(uint depositAmt) public payable {
        // need a nonzero amount to distinguish behavior; require caller supplied enough ETH
        require(depositAmt > 0, "depositAmt must be > 0");
        require(address(this).balance >= depositAmt, "contract needs ETH to forward");

        uint before = c.balances(address(this));
        // perform deposit forwarding ETH to c
        c.Deposit{value: depositAmt}();
        uint after = c.balances(address(this));

        // The distinguishing rule: balances increase iff depositAmt > MinDeposit
        // Expressed as: (after > before) == (depositAmt > c.MinDeposit())
        assert( (after > before) == (depositAmt > c.MinDeposit()) );
    }

    // allow funding this test contract so it can forward deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint before = c.balances(address(this));
        c.Deposit{value: amount}();
        uint after = c.balances(address(this));
        // General rule: after > before iff amount > MinDeposit
        // Express as implication in one assert: if amount > MinDeposit then after > before, else after == before
        uint min = c.MinDeposit();
        assert((amount > min && after > before) || (amount <= min && after == before));
    }
    receive() external payable {}
}

