contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function containing the test logic
    // params: depositor is this contract's own address use implicit, depositAmt is amount to send
    // We require this contract has enough balance to send depositAmt.
    function runTest(uint depositAmt) public {
        // need some precondition: choose depositAmt <= c.MinDeposit() to target the changed conditional
        uint minDep = c.MinDeposit();
        require(depositAmt <= minDep, "test requires depositAmt <= MinDeposit");
        require(address(this).balance >= depositAmt, "insufficient balance for test");

        // read balance before
        uint before = c.balances(address(this));

        // perform the Deposit call sending depositAmt wei
        c.Deposit{value: depositAmt}();

        // read balance after
        uint after = c.balances(address(this));

        // On the original contract P, deposits with value <= MinDeposit are ignored, so after == before.
        // On mutant M (always accepts), after would be >= before + depositAmt (specifically increased).
        assert(after == before);
    }

    // allow the contract to receive ETH so the test harness can fund it
    receive() external payable {}
    fallback() external payable {}
}

