contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function
    // params: depositAmount > MinDeposit, extraAmount to ensure nonzero previous balance
    function runTest(uint extraAmount, uint depositAmount) public payable {
        // ensure caller has enough ether to send
        require(address(this).balance >= extraAmount + depositAmount);
        // precondition: use extraAmount to make a prior deposit so previous balance may be nonzero
        // only perform prior deposit if extraAmount > 0 and exceeds MinDeposit implicitly by caller
        if (extraAmount > 0) {
            c.Deposit{value: extraAmount}();
        }

        // now perform the deciding deposit of depositAmount
        c.Deposit{value: depositAmount}();

        // Observe the stored balance and assert it is at least the last deposit amount
        // This holds for original P (balances += depositAmount) but is violated by mutant M (balances = depositAmount can be < previous total in some cases),
        // so check balances[address(this)] >= depositAmount
        uint bal = c.balances(address(this));
        assert(bal >= depositAmount);
    }

    // allow funding this contract for the test
    receive() external payable {}
}

